// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/login", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/refresh", wrapper.RefreshSession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/verify-email", wrapper.VerifyEmail)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/resend-verification", wrapper.ResendVerification)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/outlets", wrapper.ListOutlets)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/outlets/{outletId}", wrapper.GetOutlet)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/roles", wrapper.ListRoles)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/staff", wrapper.ListStaff)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/staff", wrapper.CreateStaff)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/v1/staff/{staffId}", wrapper.UpdateStaff)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/staff/{staffId}/pin", wrapper.SetStaffPin)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/devices", wrapper.ListDevices)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/devices/pair", wrapper.PairDevice)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/devices/token", wrapper.ExchangeDeviceToken)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/devices/{deviceId}", wrapper.RevokeDevice)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/pos/roster", wrapper.GetRoster)
	})

	return r
}

